    {
        "id": "b8c9d0e1-f2a3-4b5c-6d7e-8f90a1b2c3d4",
        "name": "Kummi",
        "name_ta": "கும்மி",
        "slug": "kummi",
        "short_description": "Ancient rhythmic circle dance performed by women with synchronized hand clapping, celebrating harvests and family rites.",
        "short_description_ta": "பெண்கள் வளைந்து வட்டமாக நின்று கைகொட்டி இன்னிசைப் பாட்டுடன் ஆடும் ஆதித்தமிழர் பாரம்பரிய நடனம்.",
        "description": "Kummi is one of the most ancient and unadorned folk dances of the Tamil people, mentioned in Sangam literature and celebrated in Tamil epics. Danced predominantly by women forming concentric circles, it requires no musical instruments; rhythm is created entirely through the synchronized clapping of hands, foot steps, and melodic call-and-response singing. Variations include Poonthotti Kummi (flower pot kummi), Deepa Kummi (lamp kummi), and Kulavai Kummi, performed during Pongal, ear-piercing ceremonies, and temple car festivals.",
        "description_ta": "கும்மி என்பது எந்தவித வாத்தியக் கருவிகளின் துணையுமின்றி, பெண்களின் கைத்தட்டல் ஓசையாலும் இன்னிசைப் பாடல்களாலும் மட்டுமே நிகழ்த்தப்படும் தொன்மையான நடனமாகும். சிலப்பதிகாரத்தில் குறிப்பிடப்பட்டுள்ள இக்கலை அறுவடைத் திருவிழா, பூப்புனித நீராட்டு விழா மற்றும் கோவில் விழாக்களில் வட்டமாக நின்று தாளத்திற்கேற்ப கை கொட்டி ஆடப்படுகிறது.",
        "origin": "Across rural Tamil Nadu (Kaveri delta & Kongu regions)",
        "origin_ta": "காவிரி டெல்டா மற்றும் கொங்கு மண்டலம்",
        "historical_period": "Ancient Sangam Period (3rd century BCE)",
        "historical_period_ta": "தொல் சங்க காலம் (பொ.ஆ.மு. 3-ஆம் நூற்றாண்டு)",
        "cultural_significance": "A democratic community art expressing feminine solidarity, agrarian abundance, and celebration of the seasons without socioeconomic barriers.",
        "cultural_significance_ta": "பெண்களின் கூட்டுணர்வை வெளிப்படுத்தும் சமத்துவக் கலை; பருவ காலங்களையும் உழவுப் பெருமையையும் பாடும் பண்பாட்டு வடிவம்.",
        "performance_style": "Concentric circle movement, synchronized rhythmic clapping, forward steps with slight knee dip, and harmonious chorus singing.",
        "performance_style_ta": "வட்ட வடிவில் சுற்றுதல், சீரான கைத்தட்டல், முழங்கால் வளைத்து முன்செல்லுதல் மற்றும் குலவையிட்டுப் பாடுதல்.",
        "costume": "Traditional cotton sarees or pavada-sattai, hair braided with fresh fragrant jasmine flowers.",
        "costume_ta": "பாரம்பரிய பருத்திச் சேலை அல்லது தாவணி, மல்லிகைப் பூ சூடிய கூந்தல்.",
        "instruments": "Human clapping and vocal harmony only; occasionally accompanied by Jalra.",
        "instruments_ta": "கைத்தட்டல் மற்றும் மனிதக் குரலிசை மட்டுமே (சில சமயம் ஜால்ரா).",
        "category_names": ["Folk Dance"],
        "district_codes": ["TN-ERO", "TN-TPR", "TN-SAL", "TN-KAR", "TN-TPJ"]
    },
